CLIP_DIR = os.path.join(VAULT, "제휴", "클립")
NAVER_SECTION = re.compile(r"^## 쇼핑커넥트 링크 \(네이버\)\s*$(.*?)(?=^## |\Z)", re.M | re.S)
MODEL = re.compile(r"\b(?=[A-Za-z0-9-]*\d)(?=[A-Za-z0-9-]*[A-Za-z])[A-Za-z0-9-]{4,}\b")
WON = re.compile(r"(\d{1,3}(?:,\d{3})+|\d{4,})\s*원")
FIELD_HINTS = {"배송": ("배송비", "무료배송", "배송"), "설치": ("설치",), "약정": ("약정", "렌탈", "임대")}
def front_matter(text):
    if not text.startswith("---"):
        return {}, text
    end = text.find("\n---", 3)
    if end < 0:
        return {}, text
    fm = {}
    for line in text[3:end].splitlines():
        if ":" in line and not line.startswith((" ", "-")):
            k, v = line.split(":", 1)
            # 클리퍼가 띄어쓰기 있는 속성 이름을 따옴표로 감싸 저장한다('"쇼핑 커넥트": …', 10-05) — 키의 따옴표도 벗긴다
            fm[k.strip().strip('"').strip("'")] = v.strip().strip('"').strip("'")
    return fm, text[end + 4:]
