def products(clips, targets):
    """쇼핑커넥트 링크 → 상품 증거. 클립의 쇼핑커넥트 링크가 같거나 상품 번호가 같은 클립을 붙인다(키워드 짝과 무관)."""
    out = {}
    for t in targets:
        pid = (re.search(r"/products/(\d+)", t["url"]) or [None, None])[1]
        cs = [c for c in clips if (c.get("connect") and c["connect"] == t["connect"]) or (pid and c.get("pid") == pid)]
        e = out.setdefault(t["connect"], {"상품명": t["name"], "keywords": [], "pid": pid, "clips": [], "가격": None, "가격_후보": []})
        e["keywords"] = sorted(set(e["keywords"]) | {t["keyword"]})
        e["pid"] = e["pid"] or pid
        for c in cs:
            if c["clip"] not in e["clips"]:
                e["clips"].append(c["clip"])
                e["가격"] = e["가격"] or c["가격"]
                e["가격_후보"] += [w for w in c["가격_후보"] if w not in e["가격_후보"]]
        e["증거"] = bool(e["가격"] or e["가격_후보"])
    return out
def parse_clip(path):
    text = open(path, encoding="utf-8").read()
    fm, body = front_matter(text)
    # 속성 이름의 띄어쓰기는 무시한다 — 클리퍼에서 직접 추가한 칸이 '쇼핑 커넥트'로 들어왔다(10-04)
    fm = {re.sub(r"\s+", "", k): v for k, v in fm.items()}
    title = fm.get("상품명") or os.path.splitext(os.path.basename(path))[0]
    seller = fm.get("판매처", "")
    # 스마트스토어 페이지 제목은 '상품명 : 스토어명'이다 — Web Clipper의 판매처 칸이 비면 여기서 읽는다(10-04)
    m_seller = re.match(r"^(.*\S)\s+:\s+([^:]{1,30})$", title)
    if m_seller:
        title = m_seller.group(1)
        seller = seller or m_seller.group(2).strip()
    price = re.sub(r"[^\d]", "", fm.get("가격", ""))
    won = []
    for m in WON.finditer(body):
        v = int(m.group(1).replace(",", ""))
        if v >= 100 and v not in won:
            won.append(v)
    missing = [] if price or won else ["판매가"]
    for name, words in FIELD_HINTS.items():
        if not any(w in body for w in words):
            missing.append(f"{name}(본문에 언급 없음 — 해당 없으면 무시)")
    return {
        "clip": os.path.relpath(path, VAULT),
        "keyword": fm.get("keyword", ""),
        "상품명": title,
        "판매처": seller,
        "원본": fm.get("source", ""),
        "클립일": fm.get("clipped", ""),
        "찾은_방법": fm.get("찾은_방법", "웹클리퍼"),
        "판매처_확인": fm.get("판매처_확인", ""),
        "가격": int(price) if price else None,
        "가격_후보": won[:8],
        "models": {t.upper() for t in MODEL.findall(title)},
        "pid": (re.search(r"/products/(\d+)", fm.get("source", "")) or [None, None])[1],
        # Web Clipper 팝업의 `쇼핑커넥트` 칸(10-04) — 발급받은 naver.me 링크. --sync-notes가 키워드 노트로 옮긴다
        "connect": (re.search(r"https?://naver\.me/[A-Za-z0-9]+", fm.get("쇼핑커넥트", "")) or [None])[0] or "",
        "빠진_값": missing,
    }


